<template><div class="page"><header class="head"><div><span class="eyebrow">RELEASE HEALTH</span><h1>版本变化</h1><p>选择项目，查看相邻版本的异常变化明细。</p></div><div class="actions"><el-select v-model="project" clearable filterable placeholder="全部项目"><el-option v-for="item in projects" :key="item" :label="item" :value="item" /></el-select><el-button :icon="Refresh" :loading="loading" @click="load">刷新</el-button></div></header><el-alert v-if="error" :title="error" type="warning" show-icon :closable="false" class="mb"/><section class="panel"><div v-if="filtered.length" class="table-wrap"><table class="comparison"><thead><tr><th>项目</th><th>旧版本</th><th>新版本</th><th>新增</th><th>增多</th><th>持续</th><th>减少</th><th>查看明细</th></tr></thead><tbody><tr v-for="row in filtered" :key="`${row.project}-${row.currentTaskId}`"><td data-label="项目"><strong>{{row.project}}</strong></td><td data-label="旧版本"><code>{{row.baselineVersion}}</code></td><td data-label="新版本"><code>{{row.currentVersion}}</code></td><td data-label="新增" :class="{alert:row.newCount>0}"><b>{{row.newCount}}</b></td><td data-label="增多" :class="{alert:row.increasedCount>0}"><b>{{row.increasedCount}}</b></td><td data-label="持续"><b>{{row.persistentCount}}</b></td><td data-label="减少" :class="{decrease:row.decreasedCount>0}"><b>{{row.decreasedCount}}</b></td><td data-label="查看明细"><el-button class="detail-action" link type="primary" @click="open(row)">查看明细 <el-icon><ArrowRight/></el-icon></el-button></td></tr></tbody></table></div><el-empty v-else description="每个项目至少需要两个不同版本的已完成任务" :image-size="80"/></section><el-dialog v-model="dialog" title="版本对比明细" width="min(820px, calc(100vw - 24px))"><div v-if="selected" class="details"><div class="summary"><span><b>{{selected.newCount}}</b>新增</span><span><b>{{selected.increasedCount}}</b>增多</span><span><b>{{selected.persistentCount}}</b>持续</span><span><b>{{selected.decreasedCount}}</b>减少</span></div><section v-for="group in groups" v-show="selected.details[group.key]?.length" :key="group.key"><strong>{{group.label}}（{{selected.details[group.key].length}}）</strong><button v-for="(item,index) in selected.details[group.key]" :key="`${item.file_path}-${index}`" @click="router.push({name:'TaskDetail',params:{taskId:selected.currentTaskId}})"><span>{{item.rule_name||item.matched_text||'未命名规则'}}</span><small>{{item.file_path||'未记录文件'}}</small></button></section></div></el-dialog></div></template>
<script setup>
import { computed, onMounted, ref } from 'vue';import { useRouter } from 'vue-router';import { ArrowRight, Refresh } from '@element-plus/icons-vue';import { compareTasks, getTasks } from '@/api/task';import { getProjects } from '@/api/log'
const router=useRouter(),loading=ref(false),error=ref(''),project=ref(''),projects=ref([]),tasks=ref([]),rows=ref([]),dialog=ref(false),selected=ref(null);const groups=[{key:'new',label:'新增异常'},{key:'increased',label:'异常增多'},{key:'persistent',label:'持续存在'},{key:'decreased',label:'异常减少'}];const filtered=computed(()=>project.value?rows.value.filter(x=>x.project===project.value):rows.value);const open=row=>{selected.value=row;dialog.value=true};const count=v=>Array.isArray(v)?v.length:0
async function load(){loading.value=true;error.value='';try{const [result,list]=await Promise.all([getTasks({page:1,page_size:200,status:'completed',sort:'updated_at'}),getProjects().catch(()=>[])]);tasks.value=Array.isArray(result?.list)?result.list:[];projects.value=Array.isArray(list)&&list.length?list:[...new Set(tasks.value.map(x=>x.project_name).filter(Boolean))];const grouped=new Map();tasks.value.forEach(t=>{if(!t.version)return;const key=t.project_name||'未命名项目';const a=grouped.get(key)||[];a.push(t);grouped.set(key,a)});const pairs=[];grouped.forEach((a,p)=>{a.sort((x,y)=>new Date(x.updated_at)-new Date(y.updated_at));for(let i=1;i<a.length;i++)if(a[i].version!==a[i-1].version)pairs.push({project:p,current:a[i],baseline:a[i-1]})});rows.value=await Promise.all(pairs.slice(-24).map(async x=>{const raw=await compareTasks(x.baseline.task_id,x.current.task_id)||{};const details=Object.fromEntries(groups.map(g=>[g.key,Array.isArray(raw[g.key])?raw[g.key]:[]]));const row={project:x.project,currentTaskId:x.current.task_id,baselineVersion:x.baseline.version,currentVersion:x.current.version,details};row.newCount=count(details.new);row.increasedCount=count(details.increased);row.persistentCount=count(details.persistent);row.decreasedCount=count(details.decreased);row.attention=row.newCount+row.increasedCount>0;return row}))}catch(e){error.value=e?.response?.data?.message||e?.message||'版本对比加载失败'}finally{loading.value=false}}onMounted(load)
</script>
<style scoped>
@media (min-width: 761px){.comparison th,.comparison td{text-align:center!important}}
.comparison td:nth-child(2) code,.comparison td:nth-child(3) code{font-size:14px;font-weight:700}
</style>
<style scoped>.page{height:100%;overflow:auto;padding:clamp(14px,2vw,26px);color:#e8edf2;background:linear-gradient(145deg,#14171b,#1b1f25 48%,#111418)}.head,.panel{border:1px solid rgba(255,255,255,.14);border-radius:12px;background:rgba(255,255,255,.07);box-shadow:0 14px 40px rgba(0,0,0,.2)}.head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;padding:20px;margin-bottom:14px}.eyebrow{display:block;margin-bottom:6px;color:#67e8f9;font:600 10px ui-monospace,monospace;letter-spacing:.14em}.head h1{margin:0;color:#f5f7fa;font-size:23px}.head p{margin:6px 0 0;color:#aeb7c3;font-size:12px}.actions{display:flex;gap:8px}.panel{padding:18px}.mb{margin-bottom:14px}.table-wrap{overflow-x:auto}.comparison{width:100%;border-collapse:collapse;min-width:760px;font-size:13px}.comparison th,.comparison td{padding:14px 12px;border-bottom:1px solid rgba(255,255,255,.1);text-align:left;white-space:nowrap}.comparison th{color:#8f9baa;background:rgba(0,0,0,.16);font-size:11px;font-weight:600;letter-spacing:.04em}.comparison tbody tr{transition:background .15s}.comparison tbody tr:hover{background:rgba(103,232,249,.07)}.comparison td:first-child{min-width:150px}.comparison td:nth-child(n+4):nth-child(-n+7){text-align:center;width:78px}.comparison td:nth-child(n+4):nth-child(-n+7) b{display:inline-flex;align-items:center;justify-content:center;min-width:30px;padding:4px 7px;border-radius:6px;color:#aeb7c3}.comparison td.alert b{color:#fb7185;background:rgba(251,113,133,.14);box-shadow:inset 0 0 0 1px rgba(251,113,133,.25)}.comparison td.decrease b{color:#67e8a5;background:rgba(103,232,165,.1)}.comparison code{color:#b9c4d0;font:11px ui-monospace,monospace}.detail-action{font-size:12px}.details{display:grid;gap:12px}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.summary span{padding:12px;border:1px solid rgba(255,255,255,.12);border-radius:7px;color:#aeb7c3}.summary b{display:block;color:#f5f7fa;font-size:22px}.details section{padding:12px;border:1px solid rgba(255,255,255,.12);border-radius:8px}.details section>strong{display:block;margin-bottom:8px}.details button{display:flex;justify-content:space-between;width:100%;padding:9px;border:0;border-top:1px solid rgba(255,255,255,.08);background:transparent;color:#dce4eb;text-align:left;cursor:pointer}.details button small{color:#929eaa}@media(max-width:760px){.head{align-items:stretch;flex-direction:column}.actions .el-select{flex:1}.panel{padding:10px}.table-wrap{overflow:visible}.comparison{display:block;min-width:0}.comparison thead{display:none}.comparison tbody,.comparison tr,.comparison td{display:block}.comparison tr{margin-bottom:10px;padding:10px;border:1px solid rgba(255,255,255,.12);border-radius:9px;background:rgba(255,255,255,.04)}.comparison td{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:8px 4px;border-bottom:1px solid rgba(255,255,255,.08);white-space:normal;text-align:right!important;width:auto!important}.comparison td:last-child{border-bottom:0}.comparison td::before{content:attr(data-label);color:#8f9baa;font-size:11px;text-align:left}.comparison td:first-child{min-width:0}.comparison td.alert,.comparison td.decrease{background:transparent}.summary{grid-template-columns:repeat(2,1fr)}} </style>
